head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
	if (typeof id !== 'string') return id;
	var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
	if (!W.strictMode) id = id.replace(/mf_/g, '');
	if (C[U[id]]) return C[U[id]];
	var r; try { r = F(id); } catch (e) {}
	if (r == undefined && W.strictMode) {
		var P = W.strictModeFrame.id + '_';
		var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
		s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
		if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
	}
	return r == undefined ? id : r;
};
scwin.onpageload = function() {
	window.log = "";
	window.log1 = "";
	window.log2 = "";
	window.log3 = "";
	window.scwinId = scwin.$w.getRuntimeId("scwin");
};
scwin.tabs1_leftCheckClick = function(checked) {
	log = "tabs1_leftCheckbox, checked = " + checked;
};
scwin.tabs1_rightCheckClick = function(checked) {
	log1 = "tabs1_rightCheckbox, checked = " + checked;
};
scwin.tab1_tabHTML = function(label) {
	return "<input type='checkbox' onmousedown='this.checked = !this.checked; window[scwinId].tabs1_leftCheckClick(this.checked);'/>" +
		label +
		"<input type='checkbox' onmousedown='this.checked = !this.checked; window[scwinId].tabs1_rightCheckClick(this.checked);'/>";
};
scwin.tab2_tabHTML = function(label) {
	return "<input type='checkbox' onmousedown='this.checked = !this.checked; window[scwinId].tabs2_leftCheckClick(this.checked);'/>" +
		label +
		"<input type='checkbox' onmousedown='this.checked = !this.checked; window[scwinId].tabs2_rightCheckClick(this.checked);'/>";
};
scwin.tabs2_leftCheckClick = function(checked) {
	log2 = "tabs2_leftCheckbox, checked = " + checked;
};
scwin.tabs2_rightCheckClick = function(checked) {
	log3 = "tabs2_rightCheckbox, checked = " + checked;
};
scwin.trigger1_onclick = function() {
	tabControl1.setTabHTML("tabs2", scwin.tab2_tabHTML);
};
scwin.setVal1 = function() {
	window[scwinId].tabs1_leftCheckClick(scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[0].checked);
};
scwin.setVal2 = function() {
	window[scwinId].tabs1_rightCheckClick(scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[2].checked);
};
scwin.setVal4 = function() {
	window[scwinId].tabs1_leftCheckClick(scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[0].checked);
};
scwin.setVal5 = function() {
	window[scwinId].tabs1_rightCheckClick(scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[2].checked);
};
scwin.setVal6 = function() {
	window[scwinId].tabs2_leftCheckClick(scwin.__getObj('tabControl1_tab_tabs2_tabHTML').childNodes[0].checked);
};
scwin.setVal7 = function() {
	window[scwinId].tabs2_rightCheckClick(scwin.__getObj('tabControl1_tab_tabs2_tabHTML').childNodes[2].checked);
};
scwin.setVal8 = function() {
	window[scwinId].tabs2_leftCheckClick(scwin.__getObj('tabControl1_tab_tabs2_tabHTML').childNodes[0].checked);
};
scwin.setVal9 = function() {
	window[scwinId].tabs2_rightCheckClick(scwin.__getObj('tabControl1_tab_tabs2_tabHTML').childNodes[2].checked);
};
scwin.checkVal1 = function() {
	return scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[0].checked = true;
};
scwin.checkVal2 = function() {
	return scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[2].checked = true;
};
scwin.checkVal3 = function() {
	return scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[0].checked = false;
};
scwin.checkVal4 = function() {
	return scwin.__getObj('tabControl1_tab_tabs1_tabHTML').childNodes[2].checked = false;
};
scwin.checkVal5 = function() {
	return scwin.__getObj('tabControl1_tab_tabs2_tabHTML').childNodes[0].checked = true;
};
scwin.checkVal6 = function() {
	return scwin.__getObj('tabControl1_tab_tabs2_tabHTML').childNodes[2].checked = true;
};
scwin.checkVal7 = function() {
